ClickHouse.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(ClickHouse, "ClickHouse") {
    Component(ClickHouse OLAP Engine, "ClickHouse OLAP Engine", "ClickHouse with AggregatingMergeTree", "Columnar database engine executing sub-second analytical queries on sanitized event streams.")
    Component(ClickHouse Keeper, "ClickHouse Keeper", "ClickHouse Keeper", "Replicated consensus module managing cluster coordination without WAN bottlenecks.")
}

Rel(ClickHouse Keeper, ClickHouse OLAP Engine, "Manages cluster coordination and consensus", "")

@enduml

Redis.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

System_Ext(Core_Services_Container, "Core Services Container", "Java / Spring Boot", "Core business logic and EMR processing.")

Container_Boundary(Redis, "Redis") {
    Component(Redis_Master_Replica_Cluster, "Redis Master/Replica Cluster", "In-memory data store, Redis Operator, volatile-lru", "Manages caching, ephemeral data, and distributed scheduling locks with high availability.")
}

Rel(Core_Services_Container, Redis_Master_Replica_Cluster, "Manages scheduling locks and transient caching", "Redis Protocol over mTLS with TLS")

@enduml

Apache Kafka.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(apache_kafka, "Apache Kafka") {
    Component(Kafka Broker Cluster, "Kafka Broker Cluster", "Java/Scala", "Manages asynchronous event-driven microservices decoupling with acks=all and MirrorMaker 2.")
    Component(Schema Registry, "Schema Registry", "Java/Confluent", "Validates event schemas prior to publishing.")
    Component(Kafka Connect, "Kafka Connect", "Java", "Streams raw events to persistent sinks and offloads sanitized historical data.")
}

Rel(Schema Registry, Kafka Broker Cluster, "Provides schema validation for events", "HTTP/REST over TLS 1.3")
Rel(Kafka Broker Cluster, Kafka Connect, "Streams raw events to persistent sinks", "Kafka Protocol")
@enduml
